-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
local addon_name = ...
LibStub("AceLocale-3.0"):NewLocale(addon_name, "enUS", true, true)
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.mop.deathknight.blood.Name"] = "Recommended"
L["rm.mop.deathknight.blood.Description"] = "Recommended for Blood tanks, chosen in the Blood specialization. Pulls from range with Outbreak, Icy Touch or Death Grip. Death Strike below half health, whenever Blood Shield is missing (from 80), and before all four Frost and Unholy runes sit full; Rune Strike near 90 runic power (Death Coil at 80 before you learn it); Outbreak, else Icy Touch and Plague Strike, for diseases, and Blood Boil to refresh them from 68; Soul Reaper under 35%; Heart Strike (Blood Strike before 60) on two Blood runes; Crimson Scourge on Death and Decay while diseases last, else Blood Boil; Blood Tap at eleven charges; then Death Strike, Heart Strike, Rune Strike and Horn of Winter. Three enemies on you: Death and Decay, a disease spread (Blood Boil with Roiling Blood, else Pestilence) and Blood Boil. Reminders: Blood Presence when you have none, Bone Shield, Horn of Winter, Mind Freeze, Rune Tap, Vampiric Blood, Icebound Fortitude, Empower Rune Weapon and Death Pact by your health, Dancing Rune Weapon on elites, Army of the Dead before a group boss. It cannot see incoming damage, so Anti-Magic Shell (off) and big defensives are yours."
L["rm.mop.deathknight.blood.simulator.Name"] = "Health-reactive (simulator)"
L["rm.mop.deathknight.blood.simulator.Description"] = "An alternative to the recommended Blood premade for raid tanks with healers, off by default: enable it and disable that one, or raise its priority. Death Strike only below 70% health, when Blood Shield is missing or about to fade, or before the Frost and Unholy runes cap, instead of on every rune; a lone Blood rune goes to Heart Strike when the Frost and Unholy runes are more than a second away. It has no area-of-effect section, and the same reminders as the recommended one."
L["rm.mop.deathknight.frost.Name"] = "Two-hander"
L["rm.mop.deathknight.frost.Description"] = "Frost with a two-handed weapon, the usual leveling setup; chosen in the Frost specialization whenever the two-weapon premade does not apply. Same opening, diseases, survival and AoE as the two-weapon premade, then Obliterate on Killing Machine, Frost Strike above 76 runic power, Howling Blast on Rime, Obliterate whenever a rune pair is full, Obliterate, Howling Blast, Plague Leech, Frost Strike at 40 and Horn of Winter. Before Obliterate (58) Death Strike spends your Unholy runes. Same reminders as the two-weapon premade."
L["rm.mop.deathknight.frost.dualwield.Name"] = "Two weapons"
L["rm.mop.deathknight.frost.dualwield.Description"] = "Recommended for Frost with two one-handed weapons (Masterfrost); chosen in the Frost specialization while your off hand holds a weapon. Pulls with Outbreak or Howling Blast (Death Grip solo). Death Strike on Dark Succor or below 35% health, Blood Tap at eleven charges, diseases (Unholy Blight, Outbreak, Howling Blast, Plague Strike), Soul Reaper under 35%, Frost Strike on Killing Machine or above 89 runic power, Howling Blast on Rime or with both Frost or both Death runes ready, Obliterate on two Unholy runes below 77 runic power, Frost Strike above 76, Obliterate, Howling Blast, Plague Leech before diseases fade with Outbreak ready, Frost Strike at 40, Horn of Winter. Three enemies on you: a disease spread, Death and Decay and Howling Blast. Reminders: Frost Presence, Pillar of Frost, Raise Dead, Empower Rune Weapon with every rune down, Horn of Winter, Mind Freeze, Icebound Fortitude and Death Pact when low, Army of the Dead before a group boss."
L["rm.mop.deathknight.unholy.Name"] = "Unholy"
L["rm.mop.deathknight.unholy.Description"] = "Recommended for Unholy, and the premade for any Death Knight Blood and Frost do not claim, including one without a specialization. Pulls from range with Outbreak or Icy Touch (Death Grip solo). Death Strike on Dark Succor or below 35% health, diseases (Unholy Blight, Outbreak, Plague Strike, Icy Touch), Blood Tap at eleven charges, Soul Reaper under 35%, Dark Transformation at five Shadow Infusion stacks, Death Coil near the runic power cap, Death and Decay on a target that will live, Scourge Strike, Death Coil on Sudden Doom or at 40, Outbreak while Unholy Strength is up, Festering Strike (Blood Strike before you learn it), Plague Leech, Horn of Winter. Three enemies on you: a disease spread, Death and Decay, Blood Boil and Icy Touch on a Frost rune. Reminders: Unholy Presence, your ghoul, Summon Gargoyle under Bloodlust or on a long elite fight, Unholy Frenzy, Empower Rune Weapon, Horn of Winter, Mind Freeze, Icebound Fortitude and Death Pact when low, Army of the Dead before a group boss; Anti-Magic Shell is off."
L["rm.mop.deathknight.unholy.simulator.Name"] = "Unholy, rune-cap pooling (simulator)"
L["rm.mop.deathknight.unholy.simulator.Description"] = "An alternative to the recommended Unholy premade, as the simulator, wowtbc.gg, Method and MaxDps play it; off by default: enable it and disable that one, or raise its priority. While Dark Transformation is down Death Coil goes to rebuilding Shadow Infusion, Scourge Strike comes first when both Unholy or both Death runes are ready, and Festering Strike first when both Blood and both Frost runes are; otherwise the same opening, diseases, AoE and reminders as the recommended one."
L["rm.retail.deathknight.blood.Name"] = "Blizzard Assisted"
L["rm.retail.deathknight.blood.Description"] = "Recommended for Blood. Highlights the spell Blizzard's Assisted Combat suggests next, the one rotation advice the game still lets an addon read in Midnight combat; it waits while you cast or channel. Alongside it, reminders for what Assisted Combat leaves to you: Vampiric Blood and Raise Dead in combat, Mind Freeze on an interruptible cast, and Icebound Fortitude and your racial cooldown whenever they are ready in combat. Enemy casts are hidden in combat, so Mind Freeze lights only where the game shows them; health is hidden on Retail, so when to use Icebound Fortitude is your call. Active mitigation timing, Anti-Magic Shell, taunts and trinkets stay with you."
L["rm.retail.deathknight.blood.guide.Name"] = "Reference (Icy Veins and Wowhead)"
L["rm.retail.deathknight.blood.guide.Description"] = "Reference only, off by default: the guides' Blood priority. In Midnight combat your buffs and the target's debuffs are hidden from addons, so the steps that read them wait there; read it, or clone it to experiment. Health and runic power are hidden on Retail, so Death Strike is used whenever you can afford it. Pulls with Death's Caress. Death Strike; Marrowrend (Death's Caress out of melee) when Bone Shield is missing, under five charges, about to expire, or Exterminate is up; during Gift of the San'layn, Death Strike, one Blood Boil, Death and Decay on Crimson Scourge and Heart Strike; Death and Decay on Crimson Scourge or four enemies; Vampiric Strike; Consumption; Blood Boil on Boiling Point, a missing Blood Plague or full charges; Heart Strike. Reminders: Raise Dead, Vampiric Blood, Reaper's Mark, Dancing Rune Weapon after Reaper's Mark, plus the Assisted premade's utility reminders."
L["rm.retail.deathknight.blood.simc.Name"] = "Deathbringer reference (SimulationCraft)"
L["rm.retail.deathknight.blood.simc.Description"] = "Reference only, off by default: SimulationCraft's Deathbringer list, which spends runic power on Death Strike for damage. Hidden combat data keeps it from running in Midnight combat, and runic power is hidden on Retail, so there is no cap dump. Death and Decay whenever it is down, Reaper's Mark, Marrowrend on Exterminate, Death's Caress for Bone Shield while runes are short (else Marrowrend), Death Strike, Blood Boil, Consumption outside Dancing Rune Weapon, Heart Strike. Reminders: Raise Dead, Dancing Rune Weapon, Vampiric Blood and the utility reminders."
L["rm.retail.deathknight.frost.Name"] = "Blizzard Assisted"
L["rm.retail.deathknight.frost.Description"] = "Recommended for Frost. Highlights the spell Blizzard's Assisted Combat suggests next, the one rotation advice the game still lets an addon read in Midnight combat; it waits while you cast or channel. Alongside it, reminders for what Assisted Combat leaves to you: Breath of Sindragosa and Raise Dead in combat, Mind Freeze on an interruptible cast, and Icebound Fortitude and your racial cooldown whenever they are ready in combat. Enemy casts are hidden in combat, so Mind Freeze lights only where the game shows them; health is hidden on Retail, so when to use Icebound Fortitude is your call."
L["rm.retail.deathknight.frost.guide.Name"] = "Reference (Icy Veins and SimulationCraft)"
L["rm.retail.deathknight.frost.guide.Description"] = "Reference only, off by default: the guides' Frost priority. Killing Machine, Rime and Razorice are hidden in Midnight combat, so it cannot run there; runic power is hidden on Retail, so there is no cap check. Obliterate on two Killing Machines or one with three runes, Frost Strike into five Razorice with Shattering Blade, Howling Blast on Rime, Obliterate on Killing Machine, Frost Strike, Obliterate; three or more enemies swap in Frostscythe and Glacial Advance; Howling Blast out of melee. Reminders: Remorseless Winter, Pillar of Frost, Breath of Sindragosa and Frostwyrm's Fury in Pillar, Reaper's Mark, Raise Dead, Empower Rune Weapon at two charges, plus the utility reminders."
L["rm.retail.deathknight.frost.wowhead.Name"] = "Reference (Wowhead)"
L["rm.retail.deathknight.frost.wowhead.Description"] = "Reference only, off by default: Wowhead's Frost order, which puts its cooldowns in the rotation. Hidden combat data keeps it from running in Midnight combat; runic power is hidden on Retail, so there is no cap check. Empower Rune Weapon at two charges, Reaper's Mark, Pillar of Frost, Breath of Sindragosa, Frostwyrm's Fury; then Obliterate on two Killing Machines or one with Exterminate, Howling Blast on Rime, Obliterate on Killing Machine, Empower Rune Weapon for a new one, Frost Strike, Obliterate, Howling Blast. Three or more enemies swap in Frostscythe and Glacial Advance."
L["rm.retail.deathknight.initial.Name"] = "Blizzard Assisted"
L["rm.retail.deathknight.initial.Description"] = "Recommended before you choose a specialization (while the game reports the Death Knight's initial specialization). Highlights the spell Blizzard's Assisted Combat suggests next, the one rotation advice the game still lets an addon read in Midnight combat; it waits while you cast or channel. Alongside it, the reminders every Death Knight premade shares, each once you know its spell. When you choose a specialization at level 10, that specialization's premades take over."
L["rm.retail.deathknight.unholy.Name"] = "Blizzard Assisted"
L["rm.retail.deathknight.unholy.Description"] = "Recommended for Unholy. Highlights the spell Blizzard's Assisted Combat suggests next, the one rotation advice the game still lets an addon read in Midnight combat (it raises your ghoul and uses Army of the Dead and Dark Transformation itself); it waits while you cast or channel. Alongside it: Mind Freeze on an interruptible cast, and Icebound Fortitude and your racial cooldown whenever they are ready in combat. Enemy casts are hidden in combat, so Mind Freeze lights only where the game shows them; health is hidden on Retail, so when to use Icebound Fortitude is your call."
L["rm.retail.deathknight.unholy.guide.Name"] = "Reference (Icy Veins and Wowhead)"
L["rm.retail.deathknight.unholy.guide.Description"] = "Reference only, off by default: the guides' Unholy priority. Procs and plagues are hidden in Midnight combat, so it cannot run there; runic power and the target's health are hidden on Retail, so the execute window and the San'layn runic power spend are left out. Raise Dead without a ghoul; Festering Scythe to keep its plague haste up; Soul Reaper on Reaping; Putrefy during Dark Transformation; Death Coil (Epidemic on four or more enemies) on Sudden Doom or Forbidden Knowledge; Festering Strike with no Lesser Ghoul charges, Scourge Strike with them; Death Coil. Reminders: Army of the Dead, Dark Transformation, Outbreak when your plagues are missing, plus the utility reminders."
L["rm.retail.deathknight.unholy.simc.Name"] = "Reference (SimulationCraft)"
L["rm.retail.deathknight.unholy.simc.Description"] = "Reference only, off by default: SimulationCraft's Unholy list, which spends Death Coil far more often. Hidden combat data keeps it from running in Midnight combat; runic power and target health are hidden on Retail, so the cap and execute checks are left out. Festering Scythe upkeep, Soul Reaper in Dark Transformation, Death Coil on Sudden Doom, Putrefy in Dark Transformation, Death Coil in Dark Transformation or Forbidden Knowledge and whenever Army of the Dead is over 5 seconds away, Scourge Strike with Lesser Ghoul charges, Festering Strike. Three or more enemies: Epidemic for Death Coil and Festering Strike below three charges. Reminders: Outbreak, Death and Decay on packs, Army of the Dead, Dark Transformation."
